// Play vs Bot — game store. The rules engine and the bot come from optcg-ai
// (src/optcg, generated by its scripts/sync-sn.ts). The state stays a plain
// serializable GameState; every change is an Action applied by the engine and
// appended to the GameRecord (replays + learning on the server).

import { create } from "zustand";
import {
  actionLabel,
  actor,
  applyAction,
  describePrompt,
  newGame,
  startRecord,
  stepLabel,
  trace,
  cardName,
  type Action,
  type BotLevel,
  type EngineBundle,
  type GameRecord,
  type GameState,
  type LearnedParams,
  type MetaDeck,
  type Seat,
} from "../../optcg/bot";

/** JSON call to the Sailing Network API (session cookie included). */
async function api<T = unknown>(path: string, init: RequestInit = {}): Promise<T> {
  const res = await fetch(path, { credentials: "include", headers: init.body ? { "content-type": "application/json" } : undefined, ...init });
  if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
  return (await res.json()) as T;
}

export type Mode = "human" | "spectate";
export type FirstChoice = "random" | "human" | "bot";

export interface LogLine {
  text: string;
  seat: Seat | null;
  /** index in record.actions of the action that produced the line (for feedback) */
  actionIndex: number;
  kind: "action" | "effect" | "info";
}

interface BotStore {
  stage: "loading" | "pick" | "game";
  error: string | null;
  bundle: EngineBundle | null;
  learned: LearnedParams | null;
  // setup
  mode: Mode;
  humanDeck: number;
  botDeck: number;
  level: BotLevel;
  first: FirstChoice;
  // game
  game: GameState | null;
  record: GameRecord | null;
  humanSeat: Seat;
  log: LogLine[];
  thinking: boolean;
  savedId: string | null;
  flagged: number[];
  selected: number | null;
  inspect: string | null;

  load(): Promise<void>;
  setup(p: Partial<Pick<BotStore, "mode" | "humanDeck" | "botDeck" | "level" | "first">>): void;
  start(): void;
  play(a: Action): void;
  select(uid: number | null): void;
  setInspect(id: string | null): void;
  flag(actionIndex: number): void;
  leave(): void;
}

// ---------------------------------------------------------------------------
// bot worker

let worker: Worker | null = null;
let nextId = 1;
const waiting = new Map<number, (a: Action | null) => void>();

function getWorker(): Worker {
  if (!worker) {
    worker = new Worker(new URL("./bot.worker.ts", import.meta.url), { type: "module" });
    worker.onmessage = (e: MessageEvent<{ id: number; action?: Action; error?: string }>) => {
      const done = waiting.get(e.data.id);
      waiting.delete(e.data.id);
      if (e.data.error) console.error("bot error:", e.data.error);
      done?.(e.data.action ?? null);
    };
  }
  return worker;
}

function askBot(state: GameState, seat: Seat, level: BotLevel): Promise<Action | null> {
  const id = nextId++;
  return new Promise((resolve) => {
    waiting.set(id, resolve);
    getWorker().postMessage({ id, state, seat, level, seed: (Math.random() * 2 ** 31) >>> 0 });
  });
}

// ---------------------------------------------------------------------------

const BOT_DELAY_MS = 260;
let session = 0;

export const useBotStore = create<BotStore>((set, get) => {
  /** Apply one action to the game (human or bot), with log lines. */
  function apply(a: Action): boolean {
    const { game, record, bundle } = get();
    if (!game || !record || !bundle) return false;
    const db = bundle.db;
    const who = actor(game);
    const index = record.actions.length;
    const lines: LogLine[] = [];
    if (game.prompt?.kind !== "mulligan" && a.type !== "pick" && a.type !== "done") {
      lines.push({ text: actionLabel(db, game, a), seat: who, actionIndex: index, kind: "action" });
    }
    let next: GameState;
    trace.hook = (act, step) => {
      const label = stepLabel(step.effect);
      if (!label) return;
      const targets = act.targets.flat().map((u) => cardName(db, game, u)).join(", ");
      lines.push({ text: `${db[act.cardId]?.name ?? "?"}: ${label}${targets ? " → " + targets : ""}`, seat: act.controller, actionIndex: index, kind: "effect" });
    };
    try {
      next = applyAction(db, game, a);
    } catch (err) {
      console.error("illegal action", a, err);
      return false;
    } finally {
      trace.hook = null;
    }
    const rec: GameRecord = { ...record, actions: [...record.actions, a], turns: next.turn, winner: next.winner };
    if (next.winner !== null) rec.endedAt = new Date().toISOString();
    set({ game: next, record: rec, log: [...get().log, ...lines].slice(-300), selected: null });
    if (next.winner !== null) void save();
    return true;
  }

  async function save() {
    const { record, mode, level, humanSeat, flagged } = get();
    if (!record) return;
    try {
      const r = await api<{ id: string }>("/api/bot-games", {
        method: "POST",
        body: JSON.stringify({ record, mode: mode === "human" ? "human-vs-bot" : "bot-vs-bot", level, botSeat: mode === "human" ? (1 - humanSeat) : null }),
      });
      set({ savedId: r.id });
      for (const idx of flagged) await api(`/api/bot-games/${r.id}/feedback`, { method: "POST", body: JSON.stringify({ actionIndex: idx }) });
    } catch (err) {
      console.warn("could not save the game", err);
    }
  }

  /** Let the bot move while it is its turn to decide. */
  async function runBots() {
    const my = session;
    if (get().thinking) return;
    set({ thinking: true });
    try {
      for (let guard = 0; guard < 2000; guard++) {
        const { game, mode, humanSeat, level } = get();
        if (!game || game.winner !== null || my !== session) break;
        const who = actor(game);
        if (mode === "human" && who === humanSeat) break;
        await new Promise((r) => setTimeout(r, BOT_DELAY_MS));
        const a = await askBot(game, who, level);
        if (my !== session) break;
        if (!a || !apply(a)) {
          set({ error: "Il bot non ha trovato una mossa valida." });
          break;
        }
      }
    } finally {
      if (my === session) set({ thinking: false });
    }
  }

  return {
    stage: "loading",
    error: null,
    bundle: null,
    learned: null,
    mode: "human",
    humanDeck: 0,
    botDeck: 1,
    level: "pro",
    first: "random",
    game: null,
    record: null,
    humanSeat: 0,
    log: [],
    thinking: false,
    savedId: null,
    flagged: [],
    selected: null,
    inspect: null,

    async load() {
      if (get().bundle) return set({ stage: "pick" });
      try {
        const bundle = (await (await fetch("/data/optcg/bundle.json")).json()) as EngineBundle;
        let learned: LearnedParams | null = null;
        try {
          const r = await fetch("/data/optcg/learned.json", { cache: "no-store" });
          if (r.ok) learned = (await r.json()) as LearnedParams;
        } catch {
          learned = null;
        }
        set({ bundle, learned, stage: "pick", error: null });
      } catch (err) {
        set({ error: `Dati del motore non trovati (${String(err)}). Esegui "npm run sync-sn" in optcg-ai.` });
      }
    },

    setup(p) {
      set(p);
    },

    start() {
      const { bundle, humanDeck, botDeck, first, mode, level } = get();
      if (!bundle) return;
      session++;
      const decks: [MetaDeck, MetaDeck] = [bundle.metaDecks[humanDeck], bundle.metaDecks[botDeck]];
      const humanSeat: Seat = 0;
      const firstSeat: Seat = first === "human" ? 0 : first === "bot" ? 1 : Math.random() < 0.5 ? 0 : 1;
      const seed = (Math.random() * 2 ** 31) >>> 0;
      const game = newGame(bundle.db, decks, { seed, first: firstSeat });
      const players: [string, string] = mode === "human" ? ["human", `bot:${level}`] : [`bot:${level}`, `bot:${level}`];
      const record = startRecord(decks, seed, firstSeat, players, bundle.version);
      const who = firstSeat === humanSeat && mode === "human" ? "Inizi tu." : mode === "human" ? "Inizia il bot." : "";
      set({
        stage: "game", game, record, humanSeat, savedId: null, flagged: [], selected: null, thinking: false, error: null,
        log: [{ text: `${decks[0].name} contro ${decks[1].name}. ${who}`, seat: null, actionIndex: -1, kind: "info" }],
      });
      void runBots();
    },

    play(a) {
      const { game, mode, humanSeat, thinking } = get();
      if (!game || thinking || mode !== "human" || actor(game) !== humanSeat) return;
      if (apply(a)) void runBots();
    },

    select(uid) {
      set({ selected: uid });
    },

    setInspect(id) {
      set({ inspect: id });
    },

    flag(actionIndex) {
      const { flagged, savedId } = get();
      if (flagged.includes(actionIndex)) return;
      set({ flagged: [...flagged, actionIndex] });
      if (savedId) void api(`/api/bot-games/${savedId}/feedback`, { method: "POST", body: JSON.stringify({ actionIndex }) }).catch(() => {});
    },

    leave() {
      session++;
      set({ stage: "pick", game: null, record: null, log: [], thinking: false });
    },
  };
});

export function promptText(): string {
  const { game, bundle } = useBotStore.getState();
  return game && bundle ? describePrompt(bundle.db, game) : "";
}
